package ma.lias.controller;
import ma.lias.entity.TeamChief; import ma.lias.repository.TeamChiefRepository; import ma.lias.service.AuditService; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import java.util.*;
@RestController @RequestMapping("/api/admin/team-chiefs") @PreAuthorize("hasRole('ADMIN')")
public class TeamChiefController { private final TeamChiefRepository repo; private final AuditService audit; public TeamChiefController(TeamChiefRepository repo, AuditService audit){this.repo=repo;this.audit=audit;} @GetMapping public List<TeamChief> all(){return repo.findAll();} @PostMapping public ResponseEntity<TeamChief> create(@RequestBody TeamChief body){TeamChief saved=repo.save(body); audit.log("CREATE","TeamChief",saved.getId(),"Création"); return ResponseEntity.status(HttpStatus.CREATED).body(saved);} @PutMapping("/{id}") public TeamChief update(@PathVariable Long id,@RequestBody TeamChief body){if(!repo.existsById(id)) throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Introuvable"); body.setId(id); audit.log("UPDATE","TeamChief",id,"Modification"); return repo.save(body);} }
